import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

/**
 * Custom-domain routing.
 *
 * Proxies cannot query Prisma, so connected domains are mapped with one env var:
 *
 *   CUSTOM_DOMAINS="studio.example.com=demo-studio,photos.ananya.in=ananya"
 *
 * The domain is saved in the dashboard for records, and the same pair is added
 * here (or generated by your deploy script) so requests reach the right site.
 */
function domainMap() {
  const map = new Map<string, string>();
  for (const entry of (process.env.CUSTOM_DOMAINS || "").split(",")) {
    const [domain, slug] = entry.split("=").map((part) => part?.trim().toLowerCase());
    if (domain && slug) map.set(domain, slug);
  }
  return map;
}

export function proxy(request: NextRequest) {
  const host = (request.headers.get("host") || "").split(":")[0].toLowerCase();
  if (!host || host === "localhost" || host.endsWith(".localhost")) return NextResponse.next();

  const slug = domainMap().get(host);
  if (!slug) return NextResponse.next();

  const { pathname, search } = request.nextUrl;
  if (pathname.startsWith("/s/") || pathname.startsWith("/api/")) return NextResponse.next();

  const target = request.nextUrl.clone();
  target.pathname = `/s/${slug}`;
  target.search = search;
  return NextResponse.rewrite(target);
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|icons/|favicon.ico|sw.js|manifest.webmanifest).*)"],
};
